config.script:
if self.session.custom.moveModules!=False:
	if self.session.custom.moveModules.type == self.view.params.params.type:
		moveToModules=system.util.jsonDecode(system.util.jsonEncode(self.view.params.params.config.modules))
		moveModules=system.util.jsonDecode(system.util.jsonEncode(self.session.custom.moveModules.modules))
		moveFromModules=system.util.jsonDecode(system.util.jsonEncode(self.session.custom.structure.configs[self.session.custom.moveModules.uuid]["config"]["modules"]))
		moved=[]
		stayed=[]
		originName=self.session.custom.structure.configs[self.session.custom.moveModules.uuid]["name"]
		for key in moveModules:
			if key in moveToModules and key in moveFromModules:
				for module in moveModules[key]:
				# Check if the module is already in moveToModules
					if module not in moveToModules[key]:
						moved.append(module['name'])
						moveToModules[key].append(module)  # Add to moveToModules
						try:
							moveFromModules[key].remove(module)  # Remove from moveFromModules
						except:
							pass
					else:
						if module not in moveFromModules[key]:
							moveToModules[key].append(module) 
						stayed.append(module['name'])

		self.session.custom.structure.configs[self.session.custom.moveModules.uuid]["config"]["modules"]=moveFromModules
		self.session.custom.structure.configs[self.view.params.params.uuid]["config"]["modules"]=moveToModules

		self.session.custom.moveModules=False
		message='{} of {} Module(s) have successfully been moved from "{}" to "{}"\nMoved: {}\nRetained: {}'.format(len(moved), len(moved)+len(stayed), originName, self.view.params.params.name,", ".join(moved),", ".join(stayed))

		system.perspective.sendMessage("Toast", {"message": message, "delay": 5, "color": "--success", "textColor": "Black"}, scope="session")

