customMethods.script:
containers=system.util.jsonDecode(system.util.jsonEncode(self.session.custom.containers))
uuid=self.view.params.params.uuid
for x in range(len(containers)):
	if uuid in containers[x].keys():
		containerIndex=x

if sendTo=='back':
	item=containers.pop(containerIndex)
	containers.insert(0,item)
elif sendTo=='front':
	item=containers.pop(containerIndex)
	containers.append(item)
elif sendTo=='forward':
	item=containers.pop(containerIndex)
	containers.insert(containerIndex+1,item)
elif sendTo=='backward':
	system.perspective.print(containerIndex)
	system.perspective.print(containers)	
	if containerIndex-1 > 0 and len(containers)>2:
		item=containers.pop(containerIndex)
		system.perspective.print(containerIndex)
		system.perspective.print(containers)
		containers.insert(containerIndex-1,item)
	elif len(containers)==2:
		item=containers.pop(containerIndex)
		containers.insert(0,item)
self.session.custom.containers=containers

if self.view.params.params.type== "Container":
	self.session.custom.showConnections=False
elif self.session.custom.showConnections==self.view.params.params.uuid:
	self.session.custom.showConnections=False
else:
	self.session.custom.showConnections=self.view.params.params.uuid

def remove_matching_modules(dict1, dict2):
	for key in dict1:
		if key in dict2 and isinstance(dict1[key], list) and isinstance(dict2[key], list):
			dict1[key] = [item for item in dict1[key] if item not in dict2[key]]
	return dict1
